#include <iostream>
#include <vector>
using namespace std;

vector<vector<int>> graph;
vector<int> visited;

void dfs(int v) {
    visited[v] = 1;
    for (int next : graph[v]) if (!visited[next]) dfs(next);
}

int main() {
    int n, m;
    cin >> n >> m;
    graph.assign(n + 1, {});
    visited.assign(n + 1, 0);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    int components = 0;
    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            dfs(i);
            ++components;
        }
    }
    cout << components << '\n';
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    int n, m, source;
    cin >> n >> m >> source;
    vector<vector<int>> graph(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    vector<int> dist(n + 1, -1);
    queue<int> pending;
    dist[source] = 0;
    pending.push(source);
    while (!pending.empty()) {
        int v = pending.front();
        pending.pop();
        for (int next : graph[v]) {
            if (dist[next] == -1) {
                dist[next] = dist[v] + 1;
                pending.push(next);
            }
        }
    }
    for (int i = 1; i <= n; ++i) cout << dist[i] << ' ';
    return 0;
}
